        },
        {
          "other_code": "N_abf8e3d45341fa86",
          "rule": "本节点关注射频电路硬件实现（如混频器、VCO）；兄弟节点关注信号在时频域的数学处理及通信原理。"
        }
      ],
      "cross_boundary_rule": "若重点在于电路元件在高频下的阻抗匹配、稳定性及振荡特性，归入本节点；若重点在于信号调制解调的数学原理或通信协议，归入信号处理与通信传输。"
    },
    {
      "node_code": "N_d47b1dc3f1411e3f",
      "definition": "研究用于信号选择、抑制干扰及波形整形的电路网络，涵盖无源、有源及开关电容滤波器的设计理论、拓扑结构及性能指标分析。",
      "boundary": "聚焦于滤波器的频率响应设计（如巴特沃斯、切比雪夫）、无源LC/RC网络、有源运放拓扑（Sallen-Key等）及开关电容滤波器。边界包括：1. 无源滤波器设计；2. 有源滤波器拓扑；3. 开关电容滤波原理。若内容涉及数字信号处理算法（如FIR/IIR滤波器系数计算）或通信信道均衡，则不在此列。",
      "includes": [
        "无源RC/LC滤波器、腔体及声表面波（SAW）滤波器设计",
        "有源滤波器（巴特沃斯、切比雪夫等）及Sallen-Key等拓扑结构",
        "开关电容滤波器原理、积分器及噪声分析"
      ],
      "excludes": [
        "数字信号处理中的FIR/IIR滤波器算法与系数设计",
        "通信系统中的信道均衡与自适应滤波算法"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_fbf790997a341add",
          "rule": "本节点关注特定频率响应的网络设计；兄弟节点关注通用模拟信号的放大、偏置及线性化处理。"
        },
        {
          "other_code": "N_abf8e3d45341fa86",
          "rule": "本节点关注模拟/混合信号滤波电路硬件实现；兄弟节点关注信号处理的数学变换及数字滤波算法。"
        }
      ],
      "cross_boundary_rule": "若重点在于电路元件构成的网络频率响应特性，归入本节点；若重点在于数字域滤波算法或通信协议中的均衡技术，归入信号处理与通信传输。"
    }
  ]
}
